def ensure_programs(apps, schema_editor):
    Program = apps.get_model('lynx', 'Program')
    existing = {p.program: p for p in Program.objects.all()}
    to_create = []
    for program in set(BOOL_TO_PROGRAM.values()):
        if program not in existing:
            long_name = PROGRAM_LONG_NAMES.get(program, program)
            min_age, max_age = PROGRAM_AGES.get(program, DEFAULT_AGES)
            to_create.append(Program(
                program=program,
                long_name=long_name,
                is_oib=program in OIB_PROGRAMS,
                min_age=min_age,
                max_age=max_age,
            ))
    if to_create:
        Program.objects.bulk_create(to_create, ignore_conflicts=True)

