def pick_start_date(contact, Intake):
    latest_intake = (
        Intake.objects
        .filter(contact_id=contact.id)
        .exclude(intake_date__isnull=True)
        .order_by('-intake_date')
        .first()
    )
    if latest_intake and latest_intake.intake_date:
        return latest_intake.intake_date
    if getattr(contact, 'created', None):
        return contact.created.date() if hasattr(contact.created, 'date') else contact.created
    return date.today()

