    fields = ['id'] + list(BOOL_TO_PROGRAM.keys()) + ['careers_plus_youth']
    qs = Contact.objects.only(*fields)

    batch = []
    BATCH = 1000

    def flush():
        nonlocal batch
        if batch:
            ContactProgram.objects.bulk_create(batch, ignore_conflicts=True)
            batch = []

    for c in qs.iterator(chunk_size=2000):
        start = pick_start_date(c, Intake)
        # Migrate all legacy booleans except careers_plus_youth
        for field, program in BOOL_TO_PROGRAM.items():
            if getattr(c, field, False):
                p = prog_by_code.get(program)
                if not p:
                    continue
                batch.append(ContactProgram(
                    contact_id=c.id,
                    program_id=p.id,
                    program_is_oib=p.is_oib,
                    start_date=start,
                    end_date=None,
                ))
                if len(batch) >= BATCH:
                    flush()
        # If careers_plus_youth is True, mark as careers_plus
        if getattr(c, 'careers_plus_youth', False):
            p = prog_by_code.get('CareersPlus')
            if p:
                batch.append(ContactProgram(
                    contact_id=c.id,
                    program_id=p.id,
                    program_is_oib=p.is_oib,
                    start_date=start,
                    end_date=None,
                ))
                if len(batch) >= BATCH:
                    flush()
    flush()

